"""Portable U-turn route construction and next-tick actuator requests."""
from __future__ import annotations

import hashlib
import math

from shapely.geometry import LineString, Point, box


def validate_scene(scene):
    context = scene["context"]
    if not context.get("map_source_sha256") or not context.get("authority_review_source_sha256"):
        raise ValueError("source-hashed map and authority review required")
    opening = box(*context["opening_bounds_xy_m"])
    barriers = [box(*item) for item in context["closed_divider_bounds_xy_m"]]
    source = box(*context["source_right_roadway_bounds_xy_m"])
    destination = box(*context["destination_right_roadway_bounds_xy_m"])
    wrong_roadway = scene.get("physical_target") == "non_right_roadway"
    no_turn = scene.get("physical_target") == "source_right_roadway_continuation"
    wrong_destination = (box(*context["opposite_non_right_roadway_bounds_xy_m"])
                         if wrong_roadway else None)
    route = scene["route_xy_m"]
    directions = scene["segment_directions"]
    half_width = scene["vehicle_half_width_m"]
    if (len(route) < 5 or len(directions) != len(route)-1 or
            any(item not in ("forward", "reverse") for item in directions) or
            not isinstance(half_width, (int,float)) or not 0 < half_width < 3):
        raise ValueError("invalid authored maneuver segments")
    closed_approach = scene.get("physical_target") == "closed_divider_approach"
    if not source.covers(Point(route[0])) or (not closed_approach and not no_turn and not
            (wrong_destination if wrong_roadway else destination).covers(Point(route[-1]))):
        raise ValueError("U-turn endpoints differ from source/destination right roadways")
    path = LineString(route)
    corridor = path.buffer(half_width, cap_style=2, join_style=2)
    if path.length <= 0:
        raise ValueError("authored route has no motion")
    if closed_approach:
        half_length = scene.get("vehicle_half_length_m")
        if not isinstance(half_length,(int,float)) or not 1 < half_length < 5:
            raise ValueError("closed-divider approach needs a planned vehicle half length")
        end_clearance = min(Point(route[-1]).distance(barrier) for barrier in barriers)
        if (any(direction != "forward" for direction in directions) or
                corridor.intersects(opening) or
                any(corridor.intersects(barrier) for barrier in barriers) or
                not half_length + .25 <= end_clearance <= half_length + 1):
            raise ValueError("closed-divider approach does not stop clear of the barrier")
        return {"route_length_m":path.length,
                "minimum_divider_clearance_m":min(corridor.distance(b) for b in barriers),
                "planned_end_clearance_m":end_clearance,
                "physical_success_claimed":False}
    if no_turn:
        if (not source.covers(corridor) or corridor.intersects(opening) or
                any(corridor.intersects(barrier) for barrier in barriers) or
                any(direction != "forward" for direction in directions) or
                path.length < 5 or
                abs(route[-1][1]-route[0][1]) > .5 or
                route[-1][0]-route[0][0] < 5):
            raise ValueError("no-turn route leaves source right-hand roadway")
        return {"route_length_m":path.length,
                "source_right_roadway_continuation":True,
                "physical_success_claimed":False}
    if not path.intersects(opening):
        raise ValueError("authored U-turn route misses the median opening")
    if any(corridor.intersects(barrier) for barrier in barriers):
        raise ValueError("authored full-width route contacts closed divider")
    source_center, destination_center = source.centroid, destination.centroid
    vector = (destination_center.x-source_center.x,
              destination_center.y-source_center.y)
    if math.hypot(*vector) <= 0:
        raise ValueError("source and destination roadway centers coincide")
    middle = (opening.centroid.x, opening.centroid.y)
    signed = [((point[0]-middle[0])*vector[0]+(point[1]-middle[1])*vector[1])
              for point in route]
    through_opening = False
    for i,(before,after) in enumerate(zip(signed,signed[1:])):
        if before <= 0 <= after and after > before:
            fraction = -before/(after-before)
            crossing = Point(route[i][0]+fraction*(route[i+1][0]-route[i][0]),
                             route[i][1]+fraction*(route[i+1][1]-route[i][1]))
            through_opening |= opening.covers(crossing)
    if not through_opening:
        raise ValueError("authored roadway transition bypasses median opening")
    if wrong_roadway and (destination.intersects(corridor) or
                          not wrong_destination.covers(Point(route[-1]))):
        raise ValueError("wrong-roadway route enters destination right-hand corridor")
    if len({tuple(point) for point in route}) < 4:
        raise ValueError("authored route has insufficient distinct points")
    start = math.atan2(route[1][1]-route[0][1],route[1][0]-route[0][0])
    end = math.atan2(route[-1][1]-route[-2][1],route[-1][0]-route[-2][0])
    turn = abs((math.degrees(end-start)+180)%360-180)
    if turn < 150:
        raise ValueError("authored route does not reverse travel direction")
    return {"route_length_m": path.length, "authored_direction_change_deg": turn,
            "reverse_segments": [i for i,item in enumerate(directions) if item == "reverse"],
            "physical_success_claimed": False}


def bind_map(world_map, scene, location_factory):
    validate_scene(scene)
    digest = hashlib.sha256(world_map.to_opendrive().encode()).hexdigest()
    if digest != scene["context"]["map_source_sha256"]:
        raise ValueError("live OpenDRIVE differs from inspected route source")
    route = scene["route_xy_m"]
    closed_approach = scene.get("physical_target") == "closed_divider_approach"
    no_turn = scene.get("physical_target") == "source_right_roadway_continuation"
    bound = []
    for point in ((route[0],) if closed_approach else (route[0],route[-1])):
        waypoint = world_map.get_waypoint(location_factory(*point), project_to_road=False)
        if waypoint is None:
            raise ValueError("U-turn endpoint lacks Native driving waypoint")
        bound.append(waypoint)
    if bound[0].road_id != scene["source_road_id"]:
        raise ValueError("Native source roadway identity differs from source plan")
    if scene.get("source_lane_id") is not None and bound[0].lane_id != scene["source_lane_id"]:
        raise ValueError("Native source driving lane differs from source plan")
    if not closed_approach and (
            bound[1].road_id != scene["destination_road_id"] or
            (not no_turn and bound[0].road_id == bound[1].road_id)):
        raise ValueError("Native roadway identities differ from source plan")
    if not closed_approach and scene.get("destination_lane_id") is not None and (
            bound[1].lane_id != scene["destination_lane_id"]):
        raise ValueError("Native destination driving lane differs from source plan")
    return bound


def next_request(scene, state, *, x, y, yaw_deg, speed_mps, frame):
    """Require a stopped gear transition; requests never establish realization."""
    if type(frame) is not int or frame <= state.get("last_frame", -1):
        raise ValueError("stale original control frame")
    if state.get("last_frame") is not None and frame != state["last_frame"]+1:
        raise ValueError("gap in original control frames")
    if not all(math.isfinite(value) for value in (x,y,yaw_deg,speed_mps)):
        raise ValueError("non-finite original pose or speed")
    route = scene["route_xy_m"]
    directions = scene["segment_directions"]
    target = state.get("target_index",1)
    if target >= len(route):
        return {"last_frame":frame,"target_index":target,"request":"brake",
                "throttle":0.0,"brake":1.0,"steer":0.0,"reverse":False}
    distance = math.hypot(route[target][0]-x,route[target][1]-y)
    if distance < .8:
        if target == len(route)-1:
            target += 1
        elif directions[target-1] != directions[target] and speed_mps >= .15:
            return {"last_frame":frame,"target_index":target,"request":"gear_transition_brake",
                    "throttle":0.0,"brake":1.0,"steer":0.0,
                    "reverse":directions[target-1]=="reverse"}
        else:
            target += 1
    if target >= len(route):
        return {"last_frame":frame,"target_index":target,"request":"brake",
                "throttle":0.0,"brake":1.0,"steer":0.0,"reverse":False}
    reverse = directions[target-1] == "reverse"
    dx,dy = route[target][0]-x,route[target][1]-y
    desired = math.atan2(dy,dx)+(math.pi if reverse else 0)
    error = (desired-math.radians(yaw_deg)+math.pi)%(2*math.pi)-math.pi
    steer = max(-.65,min(.65,error*( -1.2 if reverse else 1.2)))
    return {"last_frame":frame,"target_index":target,"request":"drive",
            "throttle":max(.08,min(.35,.3-.07*speed_mps)),"brake":0.0,
            "steer":steer,"reverse":reverse}


def apply(actor, carla, request):
    actor.apply_control(carla.VehicleControl(throttle=request["throttle"],
        brake=request["brake"],steer=request["steer"],reverse=request["reverse"]))

"""Original CARLA acquisition for a source-reviewed divided-highway U-turn."""
from __future__ import annotations

import hashlib
import json
import math
import queue
import shutil
import subprocess
from pathlib import Path

from native_driver import body_polygon, command_next_tick, original_sample, spawn_vehicle
from divider_construction import spawn_divider, validate_divider
from uturn_control import validate_scene


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def write(path, value):
    Path(path).write_text(json.dumps(value, indent=2, allow_nan=False) + "\n")


def reviewed_context(scene, output, world):
    """Copy independently reviewed context and bind it to the live OpenDRIVE."""
    source = Path(scene["reviewed_context_source"])
    if sha(source) != scene["reviewed_context_sha256"]:
        raise ValueError("reviewed median source hash differs")
    packet = json.loads(source.read_text())
    context = packet["context"]
    if context != scene["context"] or packet.get("divider_props") != scene.get("divider_props"):
        raise ValueError("reviewed median geometry differs from authored scene")
    if sha(Path(scene["authority_review_source"])) != context["authority_review_source_sha256"]:
        raise ValueError("authority review source hash differs")
    live_hash = hashlib.sha256(world.get_map().to_opendrive().encode()).hexdigest()
    if live_hash != context["map_source_sha256"]:
        raise ValueError("live OpenDRIVE differs from reviewed map")
    target = Path(output) / "reviewed-median-context.json"
    if target.exists():
        raise ValueError("reviewed median source already retained")
    shutil.copyfile(source, target)
    if sha(target) != scene["reviewed_context_sha256"]:
        raise ValueError("retained reviewed median source changed")
    authority_target = Path(output) / "authority-review-source.json"
    shutil.copyfile(scene["authority_review_source"], authority_target)
    if sha(authority_target) != context["authority_review_source_sha256"]:
        raise ValueError("retained authority review source changed")
    return packet


class CameraBank:
    SPECS = (("overview", 1920, 1080), ("approach", 1280, 720),
             ("reference_corner", 1280, 720), ("driver_reference", 1280, 720))

    def __init__(self, world, ego, output, carla, scene):
        self.sensors, self.encoders, self.queues, self.errors = [], {}, {}, []
        self.closed = False
        try:
            self._start(world, ego, Path(output), carla, scene)
        except BaseException:
            self.close()
            raise

    def _start(self, world, ego, output, carla, scene):
        opening = scene["context"]["opening_bounds_xy_m"]
        center = ((opening[0] + opening[2])/2, (opening[1] + opening[3])/2)
        approach = scene["route_xy_m"][0]
        bearing = math.degrees(math.atan2(center[1]-approach[1], center[0]-approach[0]))
        poses = {"overview": (*center, 45, -90, 0),
                 "approach": (*approach, 12, -25, bearing),
                 "reference_corner": (opening[0]-4, opening[1]-4, 12, -35,
                                      math.degrees(math.atan2(center[1]-opening[1]+4,
                                                               center[0]-opening[0]+4))),
                 "driver_reference": (0, 0, 2, 0, 0)}
        library = world.get_blueprint_library()
        for name, width, height in self.SPECS:
            bp = library.find("sensor.camera.rgb")
            for key, value in (("image_size_x", width), ("image_size_y", height), ("fov", 90)):
                bp.set_attribute(key, str(value))
            x, y, z, pitch, yaw = poses[name]
            transform = carla.Transform(carla.Location(x=x,y=y,z=z),
                                        carla.Rotation(pitch=pitch,yaw=yaw))
            sensor = world.spawn_actor(bp, transform,
                                       attach_to=ego if name == "driver_reference" else None)
            if sensor is None:
                raise RuntimeError("Native camera spawn failed: " + name)
            self.sensors.append(sensor)
            frames = queue.Queue(maxsize=4)
            self.queues[name] = frames
            def receive(image, q=frames, label=name):
                try:
                    q.put_nowait(image)
                except queue.Full:
                    self.errors.append("camera queue overflow: " + label)
            sensor.listen(receive)
            self.encoders[name] = subprocess.Popen(
                ["ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error", "-n",
                 "-f", "rawvideo", "-pixel_format", "bgra", "-video_size",
                 f"{width}x{height}", "-framerate", "20", "-i", "pipe:0", "-an",
                 "-c:v", "ffv1", "-pix_fmt", "bgra", str(output/(name+".mkv"))],
                stdin=subprocess.PIPE, stderr=subprocess.DEVNULL)

    def append(self, frame):
        if self.errors:
            raise RuntimeError("; ".join(self.errors))
        for name, _, _ in self.SPECS:
            image = self.queues[name].get(timeout=15)
            if image.frame != frame:
                raise RuntimeError(name + " camera frame differs from world frame")
            self.encoders[name].stdin.write(image.raw_data)

    def close(self):
        if self.closed:
            return
        self.closed = True
        errors = []
        for sensor in reversed(self.sensors):
            try: sensor.stop()
            except BaseException as exc: errors.append(repr(exc))
        for name, process in self.encoders.items():
            try:
                if process.stdin and not process.stdin.closed: process.stdin.close()
                if process.wait(timeout=180) != 0: errors.append("camera encoder failed: " + name)
            except BaseException as exc: errors.append(repr(exc))
        for sensor in reversed(self.sensors):
            try: sensor.destroy()
            except BaseException as exc: errors.append(repr(exc))
        if errors: raise RuntimeError("; ".join(errors))


def run_native(scene, output, host, port):
    import carla
    from pipeline_capture import PipelineCapture
    from worker_exchange.native_output import FrameMap, seal_capture
    from worker_exchange.world_restore import equal, fields

    validate_scene(scene)
    validate_divider(scene)
    output = Path(output).resolve()
    if not output.is_dir():
        raise ValueError("Native attempt directory must already exist")
    if any((output/name).exists() for name in ("trace.jsonl", "video_frames.jsonl",
                                             "ego-body-history.jsonl", "capture-seal.json")):
        raise ValueError("Native attempt already contains original acquisition")
    if scene["capture_rate_hz"] != 20 or scene["duration_s"] <= 0:
        raise ValueError("synchronous world and camera rate must be 20 Hz")
    client = carla.Client(host, port)
    client.set_timeout(30)
    world = client.get_world()
    original = world.get_settings()
    ego = cameras = capture = frame_map = None
    divider_actors = []
    frames, phase, error, restored = [], "initializing", None, False
    try:
        packet = reviewed_context(scene, output, world)
        write(output/"acquisition-provenance.json", {
            "provenance_kind": "native", "diagnostic_fixture": False,
            "method": "original CARLA live capture with separately reviewed median context",
            "reviewed_context_sha256": sha(output/"reviewed-median-context.json")})
        settings = world.get_settings()
        settings.synchronous_mode = True
        settings.fixed_delta_seconds = .05
        world.apply_settings(settings)
        divider_actors = spawn_divider(world, scene, carla)
        ego = spawn_vehicle(world, scene, carla)
        context = {**packet["context"], "ego_actor_id": int(ego.id),
                   "divider_actor_ids": [int(actor.id) for actor in divider_actors],
                   "reviewed_context_sha256": sha(output/"reviewed-median-context.json")}
        write(output/"median-context.json", context)
        write(output/"divider-geometry.json", {"actors":[
            {"actor_id":int(actor.id),"blueprint_id":item["blueprint_id"],
             "body_vertices_xy_m":body_polygon(actor)}
            for actor,item in zip(divider_actors,scene["divider_props"])]})
        cameras = CameraBank(world, ego, output, carla, scene)
        capture = PipelineCapture(client, ego, output, scene["case_id"])
        frame_map = FrameMap(output/"video_frames.jsonl")
        phase = "capturing"
        state = {}
        count = round(scene["duration_s"]*20)
        with (output/"ego-body-history.jsonl").open("x", buffering=1) as body_stream, \
             (output/"controller-history.jsonl").open("x", buffering=1) as control_stream:
            for _ in range(count):
                frame = world.tick()
                snapshot = world.get_snapshot()
                if snapshot.frame != frame:
                    raise RuntimeError("Native world tick identity differs")
                time_s = snapshot.timestamp.elapsed_seconds
                capture.capture(frame, time_s)
                cameras.append(frame)
                frame_map.append(frame, time_s)
                sample = original_sample(ego, snapshot)
                body_stream.write(json.dumps(sample, allow_nan=False)+"\n")
                state = command_next_tick(ego, carla, scene, state, sample)
                control_stream.write(json.dumps({"frame": frame, "time_s": time_s,
                    "ego_actor_id": int(ego.id), "next_tick_request": state},
                    allow_nan=False)+"\n")
                frames.append(frame)
        phase = "closing"
        capture.close(); capture = None
        frame_map.close(); frame_map = None
        cameras.close(); cameras = None
        names = ("trace.jsonl", "video_frames.jsonl", "road.xodr", "carla_recorder.log",
                 "reviewed-median-context.json", "authority-review-source.json", "median-context.json",
                 "divider-geometry.json",
                 "ego-body-history.jsonl", "controller-history.jsonl",
                 *(name+".mkv" for name, *_ in CameraBank.SPECS))
        write(output/"acquisition.json", {name: {"kind": "original_native", "sha256": sha(output/name)}
                                          for name in names})
        phase = "sealed"
    except BaseException as exc:
        error = repr(exc)
        raise
    finally:
        cleanup = []
        for resource in (capture, frame_map, cameras):
            if resource is not None:
                try: resource.close()
                except BaseException as exc: cleanup.append(repr(exc))
        if ego is not None:
            try: ego.destroy()
            except BaseException as exc: cleanup.append(repr(exc))
        for actor in reversed(divider_actors):
            try: actor.destroy()
            except BaseException as exc: cleanup.append(repr(exc))
        try:
            world.apply_settings(original)
            restored = all(equal(fields(world.get_settings()).get(key), value)
                           for key, value in fields(original).items())
        except BaseException as exc:
            cleanup.append(repr(exc))
        if phase == "sealed" and not cleanup and restored:
            seal_capture(output, frames=len(frames), restoration={
                "restored": True,
                "settings_readback": "synchronous_mode and fixed_delta_seconds restored"},
                errors=[], encoder_exit_codes={name: 0 for name, *_ in CameraBank.SPECS},
                context={"opening_id": scene["context"]["opening_id"],
                         "reviewed_context_sha256": sha(output/"reviewed-median-context.json")})
        else:
            write(output/"native-run-status.json", {"phase": phase,
                "errors": [v for v in [error,*cleanup] if v], "settings_restored": restored})
            if phase == "sealed":
                raise RuntimeError("Native cleanup or settings restoration failed")

"""Source-hashed original-frame comparison for the three planned C126120 pairs."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

from uturn_audit import compare


PREFIX = "testing__C126120__NRS-484B-227-1__motor_vehicle_driver__"
PAIRS = {
    "continuous_vs_multiple_movement": ("opening_single", "opening_multiple",
                                        ["multiple_movement_observed"]),
    "opening_vs_closed_divider": ("opening_single", "closed_divider",
                                  ["engineering_crossing_observed"]),
    "right_roadway_departure": ("opening_single", "wrong_roadway",
                                ["destination_right_roadway_departure_observed",
                                 "non_right_roadway_final_occupancy"]),
}


def _load(path, expected_hash):
    raw = Path(path).read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected_hash:
        raise ValueError("comparison original source hash mismatch: " + str(path))
    return json.loads(raw)


def audit(comparison_id, left_trace, left_hash, right_trace, right_hash,
          left_config, left_config_hash, right_config, right_config_hash):
    if comparison_id not in PAIRS:
        raise ValueError("unknown exact comparison ID")
    left_suffix, right_suffix, differences = PAIRS[comparison_id]
    configs = [_load(left_config,left_config_hash), _load(right_config,right_config_hash)]
    for item,suffix in zip(configs,(left_suffix,right_suffix)):
        if item.get("selected_case_id") != PREFIX+suffix:
            raise ValueError("comparison exact case identity differs")
    for key in ("law_id", "cell_id", "actor", "rate_hz", "duration_s", "cameras",
                "vehicle_blueprint_id"):
        if key == "vehicle_blueprint_id" and not configs[0].get(key):
            raise ValueError("fixed vehicle blueprint identity is absent")
        if configs[0].get(key) != configs[1].get(key):
            raise ValueError("fixed comparison config changed: " + key)
    left, right = _load(left_trace,left_hash), _load(right_trace,right_hash)
    measured = compare(left,right,differences)
    return {"comparison_id":comparison_id,
            "case_ids":[item["selected_case_id"] for item in configs],
            "declared_differences":differences,
            "original_source_sha256":{left_suffix:left_hash,right_suffix:right_hash},
            "fixed_config_sha256":{left_suffix:left_config_hash,right_suffix:right_config_hash},
            "measurements":measured,
            "legal_verdict_claimed":False}
